      style={{
        minHeight: '100vh',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        padding: '2rem',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        background: 'linear-gradient(135deg, #1a1a2e 0%, #16213e 100%)',
        color: '#e8e8e8',
      }}
    >
      <div
        style={{
          textAlign: 'center',
          maxWidth: '28rem',
        }}
      >
        <div
          style={{
            fontSize: '6rem',
            fontWeight: 700,
            color: '#e94560',
            lineHeight: 1,
            marginBottom: '1rem',
          }}
        >
          403
        </div>
        <h1
          style={{
            fontSize: '1.5rem',
            fontWeight: 600,
            marginBottom: '0.5rem',
          }}
        >
          Access Forbidden
        </h1>
        <p
          style={{
            color: '#a0a0a0',
            marginBottom: '2rem',
            lineHeight: 1.6,
          }}
        >
          You don&apos;t have permission to access this page. This area is
          restricted to administrators only.
        </p>
        <Link
          href="/"
          style={{
            display: 'inline-block',
            padding: '0.75rem 1.5rem',
            background: '#e94560',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '0.5rem',
            fontWeight: 500,
            transition: 'background 0.2s',
          }}
        >
          Return Home
        </Link>
      </div>
    </div>
  );
}

